class FileUploadError(Exception):
    pass

class FileNotFoundError(FileUploadError):
    def __init__(self, message, file_path):
        super().__init__(message)
        self.file_path = file_path

class InvalidFileTypeError(FileUploadError):
    def __init__(self, message, file_type):
        super().__init__(message)
        self.file_type = file_type

class ConnectionError(FileUploadError):
    def __init__(self, message, url):
        super().__init__(message)
        self.url = url

async def upload_file(file_path, allowed_types, server_url):
    try:
        with open(file_path, 'r') as f:
            content = f.read()
            # Simulate file reading
            if not content:
                raise FileNotFoundError(f'Empty file at {file_path}')

            # Check file type
            if not file_path.endswith('.txt'):
                raise InvalidFileTypeError(f'File type {file_path} is not allowed. Must be .txt.', file_path)

            # Simulate network request
            await asyncio.sleep(1)
            if server_url != 'example.com':  # Simulate connection error
                raise ConnectionError(f'Connection failed to {server_url}', server_url)

            return 'Upload successful'
    except FileNotFoundError as e:
        raise e
    except InvalidFileTypeError as e:
        raise e
    except ConnectionError as e:
        raise e
    except Exception as e:
        raise FileUploadError(f'An unknown error occurred: {str(e)}')

# Example usage
async def main():
    try:
        result = await upload_file('example.txt', ['txt'], 'example.com')
        print(result)
    except FileUploadError as e:
        print(f'File upload error: {str(e)}')
    except Exception as e:
        print(f'Unexpected error: {str(e)}')

asyncio.run(main())
